var ESPACIOS_MAP_DESIGN_JS = `
(function(){
  const KEY='espacios_theme_v1';
  const LIGHT_LOGO='https://espacios.me/logos/assets/brand/espacios-logo-hd.png?v=20260921';
  const DARK_LOGO='https://espacios.me/logos/assets/brand/espacios-logo-white-hd.png?v=20260921';
  let current='dark';
  let connectedMap=null;
  let paintedSignature='';
  let layerPaintTimer=0;
  document.documentElement.dataset.espaciosMapDesign='semantic-theme-v2';

  function savedTheme(){
    try{const value=localStorage.getItem(KEY);if(value==='light'||value==='dark')return value}catch(e){}
    return 'dark';
  }

  function paintMap(theme){
    const map=window.__PSR_MAP__;
    const layers=map?.getStyle?.()?.layers||[];
    if(!map||!layers.length)return;
    const light=theme==='light';
    const signature=theme+'|'+layers.length;
    if(signature===paintedSignature)return;
    paintedSignature=signature;
    const colors=light?{
      land:'#e8edf6',water:'#cbd8ec',residential:'#e2e8f2',park:'#d9e6df',ice:'#f4f7fb',building:'#d0d8e6',
      road:'#bdc7d6',roadMajor:'#aab7ca',roadCasing:'#e9eef6',rail:'#9da9bb',boundary:'#8e9bb0',
      label:'#40506b',labelSoft:'#64728a',halo:'#f4f7fc'
    }:{
      land:'#0d1320',water:'#121c2f',residential:'#111a2b',park:'#14231f',ice:'#293446',building:'#2d374a',
      road:'#3a465e',roadMajor:'#4d5b76',roadCasing:'#151d2b',rail:'#49556a',boundary:'#526077',
      label:'#b5c0d4',labelSoft:'#909db3',halo:'#0d1320'
    };
    const p=(id,prop,val)=>{try{if(map.getLayer(id))map.setPaintProperty(id,prop,val)}catch(e){}};
    const transition=(id,prop)=>p(id,prop+'-transition',{duration:180,delay:0});
    for(const layer of layers){
      const id=String(layer.id||''),key=id.toLowerCase(),source=String(layer.source||'');
      if(layer.type==='background'){transition(id,'background-color');p(id,'background-color',colors.land);continue}
      if(source!=='openmaptiles'&&source!=='ne2_shaded')continue;
      if(layer.type==='fill'){
        let color=colors.land;
        if(key.includes('water'))color=colors.water;
        else if(key.includes('park')||key.includes('wood'))color=colors.park;
        else if(key.includes('ice')||key.includes('glacier'))color=colors.ice;
        else if(key.includes('residential'))color=colors.residential;
        else if(key.includes('building'))color=colors.building;
        else if(key.includes('aeroway')||key.includes('pier'))color=light?'#d7deea':'#202a3a';
        transition(id,'fill-color');p(id,'fill-color',color);
      }else if(layer.type==='line'){
        let color=colors.road;
        if(key.includes('water'))color=light?'#9db4d3':'#344d6b';
        else if(key.includes('boundary'))color=colors.boundary;
        else if(key.includes('rail'))color=colors.rail;
        else if(key.includes('casing'))color=colors.roadCasing;
        else if(key.includes('major')||key.includes('motorway')||key.includes('runway'))color=colors.roadMajor;
        transition(id,'line-color');p(id,'line-color',color);
      }else if(layer.type==='symbol'&&layer.layout?.['text-field']){
        const soft=key.includes('other')||key.includes('suburb')||key.includes('village')||key.includes('water');
        transition(id,'text-color');p(id,'text-color',soft?colors.labelSoft:colors.label);p(id,'text-halo-color',colors.halo);
      }
    }
    p('project-clusters','circle-color',light?'#f7f9fd':'#182238');
    p('project-clusters','circle-stroke-color',light?'#4459c7':'#a9b5ff');
    p('project-cluster-count','text-color',light?'#172033':'#f3f6ff');
    p('project-cluster-count','text-halo-color',colors.halo);
    p('project-points','circle-stroke-color',light?'#4459c7':'#a9b5ff');
    p('community-points','circle-color',light?'#6679d4':'#93a2ef');
    p('community-points','circle-stroke-color',light?'#f8faff':'#f3f6ff');
    p('initiative-points','circle-color',light?'#c77955':'#e3a079');
    p('initiative-points','circle-stroke-color',light?'#fff7f1':'#fff5ee');
    p('selection-halo','circle-color',light?'rgba(68,89,199,.13)':'rgba(169,181,255,.15)');
    p('selection-halo','circle-stroke-color',light?'#4459c7':'#a9b5ff');
    p('psr-3d-buildings','fill-extrusion-color',light?'#b7c3d6':'#3d475b');
    for(const id of ['project-labels','project-footprint-labels','project-unresolved-labels','community-labels','psr-community-polygon-labels','psr-community-selected-label','psr-official-district-label','psr-universal-selected-label']){p(id,'text-color',colors.label);p(id,'text-halo-color',colors.halo)}
    for(const id of ['psr-emirate-fill','psr-community-base','psr-master-territory-base','psr-universal-emirate-base','psr-universal-community-base'])p(id,'fill-color',light?'rgba(73,91,124,.055)':'rgba(153,170,207,.045)');
    for(const id of ['psr-emirate-line','psr-community-line','psr-master-territory-line'])p(id,'line-color',light?'rgba(74,91,124,.4)':'rgba(161,176,209,.32)');
    try{map.getCanvas().style.background=colors.land}catch(e){}
  }

  function syncControl(){
    document.querySelectorAll('.theme-radio-map label').forEach(label=>{
      const input=label.querySelector('input');
      const on=input&&input.value===current;
      label.classList.toggle('is-selected',!!on);
      if(input)input.checked=!!on;
    });
  }

  function applyTheme(theme,persist){
    current=theme==='light'?'light':'dark';
    paintedSignature='';
    document.documentElement.dataset.espaciosTheme=current;
    document.documentElement.style.colorScheme=current;
    document.querySelector('meta[name="theme-color"]')?.setAttribute('content',current==='light'?'#edf3fb':'#0d1320');
    const logo=document.querySelector('.espacios-map-logo');
    if(logo)logo.src=current==='dark'?DARK_LOGO:LIGHT_LOGO;
    if(persist){try{localStorage.setItem(KEY,current)}catch(e){}}
    syncControl();
    paintMap(current);
  }

  function addControl(){
    const topbar=document.querySelector('.topbar');
    if(!topbar||topbar.querySelector('.theme-radio-map'))return;
    const field=document.createElement('fieldset');
    field.className='theme-radio-map';
    field.setAttribute('aria-label','Color theme');
    field.innerHTML='<legend>Color theme</legend><label aria-label="Use light theme" title="Light theme"><input type="radio" name="espacios-map-theme" value="light"><span aria-hidden="true" class="theme-radio-dot is-light"></span><b>Light</b></label><label aria-label="Use dark theme" title="Dark theme"><input type="radio" name="espacios-map-theme" value="dark"><span aria-hidden="true" class="theme-radio-dot is-dark"></span><b>Dark</b></label>';
    field.addEventListener('change',event=>{const value=event.target?.value;if(value==='light'||value==='dark')applyTheme(value,true)});
    topbar.insertBefore(field,document.querySelector('.sync-pill'));
    syncControl();
  }

  function connectMap(){
    const map=window.__PSR_MAP__;
    if(!map){setTimeout(connectMap,125);return}
    if(connectedMap!==map){connectedMap=map;map.on?.('style.load',()=>{paintedSignature='';paintMap(current)});map.on?.('load',()=>{paintedSignature='';paintMap(current)});map.once?.('idle',()=>{paintedSignature='';paintMap(current)})}
    paintMap(current);
  }

  document.querySelectorAll('.eyebrow').forEach(node=>{if(node.textContent.trim()==='AE AI')node.textContent='ESPACIOS AI'});
  const aiRail=document.querySelector('[data-panel="ai"]');
  if(aiRail)aiRail.title='Ask Espacios AI';
  const ask=document.querySelector('#ai-ask');
  if(ask)ask.textContent='Ask Espacios AI';
  addControl();
  applyTheme(savedTheme(),false);
  connectMap();
  window.__ESPACIOS_PAINT_MAP__=()=>{clearTimeout(layerPaintTimer);layerPaintTimer=setTimeout(()=>{paintedSignature='';paintMap(current)},0)};
  window.addEventListener('storage',event=>{if(event.key===KEY&&(event.newValue==='light'||event.newValue==='dark'))applyTheme(event.newValue,false)});
})();
`;
var ESPACIOS_THEME_BOOTSTRAP = `<script id="espacios-theme-bootstrap">(function(){var t='dark';try{var s=localStorage.getItem('espacios_theme_v1');if(s==='light'||s==='dark')t=s}catch(e){}document.documentElement.dataset.espaciosTheme=t;document.documentElement.style.colorScheme=t;var m=document.querySelector('meta[name="theme-color"]');if(m)m.setAttribute('content',t==='light'?'#edf3fb':'#0d1320')})()<\/script>`;
