var AE_KNOWLEDGE_ROADMAP_JS = `
(function(){
  var block='<section class="ar-block" id="ae-knowledge-roadmap"><h3>Knowledge</h3><p>1,382 projects in the workbook. 1,063 recorded asks. 704 mapped to a Dubai market-area history. 528 can show a scenario. Approved project forecasts: 0.</p><p>An ask is not a closed sale. A historical project price here is a backcast from today\\'s ask using area movement, not an observed sale of that project. 2027\u20132030 figures are scenarios, not forecasts. Dubai history is not copied into the other emirates. Blank means unsupported.</p><h3>Roadmap</h3><p>Next: match each project and building to the 1,364,226 Dubai transaction rows and keep the source on every point. Still missing: same-unit repeat sales, ask revisions, project rents and yields, unit absorption, delivery performance, and any approved forecast.</p><p><a href="/map/research#knowledge">Knowledge</a> \xB7 <a href="/map/intelligence#roadmap">Roadmap</a></p></section>';
  function place(){
    var panel=document.querySelector('#analyze-panel');
    if(!panel||panel.querySelector('#ae-knowledge-roadmap')) return !!panel;
    var title=panel.querySelector('.panel-title-row');
    var holder=document.createElement('div');
    holder.innerHTML=block;
    var node=holder.firstElementChild;
    if(title) title.insertAdjacentElement('afterend', node);
    else panel.insertBefore(node, panel.firstChild);
    return true;
  }
  if(!place()){
    var obs=new MutationObserver(function(){ if(place()) obs.disconnect(); });
    obs.observe(document.documentElement,{childList:true,subtree:true});
    setTimeout(function(){ obs.disconnect(); }, 20000);
  }
})();
`;
