  const q = await env.DB.prepare("SELECT o.id,o.metric_key,o.scope_type,o.scope_key,o.scope_label,o.value_numeric,o.unit,o.currency_code,o.period_start,o.period_end,o.published_at,o.fresh_until,o.provenance_note,s.publisher,s.label AS source_label,s.canonical_url FROM psr_market_observations o JOIN psr_market_data_sources s ON s.id=o.source_id WHERE o.status='published' AND s.status='active' AND date(o.period_end)<=date('now') AND date(o.published_at)<=date('now') AND o.metric_key NOT LIKE 'projected_%' ORDER BY o.scope_type,o.scope_key,o.period_end").all();
