const apiURL=path=>'/map/api/'+path;
async function api(path){if(cache.has(path))return cache.get(path);const promise=(async()=>{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);try{const r=await fetch(apiURL(path),{signal:controller.signal,credentials:'same-origin'});if(!r.ok)throw Error('HTTP '+r.status);const d=await r.json();if(d.error)throw Error(d.error);errors.delete(path);return d;}catch(e){cache.delete(path);errors.set(path,e.name==='AbortError'?'Request timed out':e.message);throw e;}finally{clearTimeout(timer);}})();cache.set(path,promise);return promise;}
