 exportMeta={dataset:d.id,rows:filtered,sourceApi:apiURL(d.api),sourceVersion:data.version,sourceAsOf:data.asOf||data.capturedAt||data.generatedAt,sourceMetadata:Object.fromEntries(['sources','source','methodology','method','periodPolicy','mixedPolicy','policy','retention','asOf','capturedAt','generatedAt','latestDate'].filter(k=>data[k]!==undefined).map(k=>[k,data[k]])),filters:{q:state.q,emirate:state.emirate,segment:state.segment,period:state.period},totalMatching:filtered.length,scope:'All matching records in this dataset response',limitations:[d.note],caption:n(filtered.length)+' matching records \xB7 '+d.grain};
