async function sourceRows(){const paths=['market-segments','history-library?limit=1','abu-dhabi-evidence','history-catalogue','forecast-evidence'];const data=await Promise.all(paths.map(optional));const rows=[];data.forEach((d,i)=>{if(!d)return;const sources=d.sources||d.source||[];const entries=Array.isArray(sources)?sources.map((s,j)=>[s.id||j,s]):Object.entries(sources);for(const [key,s]of entries){if(s&&typeof s==='object')rows.push({sourceFamily:paths[i].split('?')[0],id:s.id||key,...s});}if(paths[i]==='forecast-evidence'){for(const s of d.records||[])rows.push({sourceFamily:'catalyst record',...s});for(const s of d.dataSources||[])rows.push({sourceFamily:'acquisition / rights; not ingested',...s});}});return rows.map(r=>({...r,displayLabel:r.label||r.title||r.id||r.initiativeId||'Source reference'}));}
